import Foundation

/// A set of sounds, one per `SoundMoment` (design §3.8). v1 ships Classic; the format allows
/// more packs later (for example unlocked by badges): add a case and its files.
///
/// Files live in `Resources/Sounds` as `<pack>-<moment>.caf` (mono AAC), generated by
/// `apps/ios/Tools/generate-sounds.swift`.
nonisolated enum SoundPack: String, Hashable, Sendable, CaseIterable {
    case classic

    /// Literal name for Settings.
    var title: String {
        switch self {
        case .classic: "Classic"
        }
    }

    /// The bundled file (without extension) for a moment.
    func resourceName(for moment: SoundMoment) -> String {
        "\(rawValue)-\(Self.slug(for: moment))"
    }

    static let fileExtension = "caf"

    /// Moments whose Classic sound is a synthesized placeholder.
    /// TODO(sound): replace these with professionally produced sounds (same names, ≤ 1.5 s,
    /// peak −6 dBFS) and empty this set. Only the winner's neigh is final.
    static let placeholderMoments: Set<SoundMoment> = Set(SoundMoment.allCases).subtracting([.winner])

    func isPlaceholder(_ moment: SoundMoment) -> Bool {
        self == .classic && Self.placeholderMoments.contains(moment)
    }

    /// The longest a moment may run (design §3.8): 1.5 s, except the neigh (3 s).
    static func maximumDuration(for moment: SoundMoment) -> TimeInterval {
        moment == .winner ? 3.0 : 1.5
    }

    /// Playback volume: quiet by default. The files are already peak-normalized to −6 dBFS.
    static let volume: Float = 0.7

    private static func slug(for moment: SoundMoment) -> String {
        switch moment {
        case .liveKnock: "live-knock"
        case .knockLanded: "knock-landed"
        case .knockTied: "knock-tied"
        case .knockFailed: "knock-failed"
        case .redKing: "red-king"
        case .roundSaved: "round-saved"
        case .tauntReceived: "taunt-received"
        case .winner: "winner"
        case .deadLast: "dead-last"
        case .debut: "debut"
        }
    }
}
